static unsigned char* g_trust_atlas;
static int g_trust_atlas_w, g_trust_atlas_h;

static int trust_atlas_ready(void)
{
    if (g_trust_atlas) return 1;
    int comp = 0;
    g_trust_atlas = stbi_load_from_memory(kTrustFaceAtlas, (int)sizeof kTrustFaceAtlas,
        &g_trust_atlas_w, &g_trust_atlas_h, &comp, 4);
    return g_trust_atlas != NULL && g_trust_atlas_w >= TRUST_FACE_COLUMNS * TRUST_FACE_CELL;
}

int res_trust_face_rgba(uint32_t spell, uint8_t** rgba, int* width, int* height)
{
    if (!rgba || !width || !height) return 0;
    *rgba = NULL; *width = *height = 0;
    int slot = -1;
    for (size_t i = 0; i < sizeof kTrustFaces / sizeof kTrustFaces[0]; ++i)
        if (kTrustFaces[i].spell == spell) { slot = kTrustFaces[i].slot; break; }
    if (slot < 0 || !trust_atlas_ready()) return 0;
    const int sx = (slot % TRUST_FACE_COLUMNS) * TRUST_FACE_CELL;
    const int sy = (slot / TRUST_FACE_COLUMNS) * TRUST_FACE_CELL;
    if (sx + TRUST_FACE_CELL > g_trust_atlas_w || sy + TRUST_FACE_CELL > g_trust_atlas_h) return 0;
    uint8_t* out = (uint8_t*)malloc((size_t)TRUST_FACE_CELL * TRUST_FACE_CELL * 4);
    if (!out) return 0;
    for (int y = 0; y < TRUST_FACE_CELL; ++y)
        memcpy(out + (size_t)y * TRUST_FACE_CELL * 4,
            g_trust_atlas + ((size_t)(sy + y) * g_trust_atlas_w + sx) * 4,
            (size_t)TRUST_FACE_CELL * 4);
    *rgba = out; *width = *height = TRUST_FACE_CELL;
    return 1;
}

void res_trust_faces_shutdown(void)
{
    if (g_trust_atlas) stbi_image_free(g_trust_atlas);
    g_trust_atlas = NULL;
    g_trust_atlas_w = g_trust_atlas_h = 0;
}
